package com.example.shortener.feature.link.controller;
import com.example.shortener.feature.link.dto.LinkForm; import com.example.shortener.feature.link.service.ShortLinkService; import jakarta.validation.Valid; import org.springframework.data.domain.PageRequest; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/links") public class LinkRestController { private final ShortLinkService s; public LinkRestController(ShortLinkService s){this.s=s;} @GetMapping public Object list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String q,Authentication a){var p=PageRequest.of(page,size);var result=q==null||q.isBlank()?s.findByUser(a.getName(),p):s.search(a.getName(),q,p);return result.map(l->Map.of("id",l.getId(),"code",l.getCode(),"url",l.getOriginalUrl(),"tags",l.getTags().stream().map(t->t.getName()).toList()));} @PostMapping public Object create(@Valid @RequestBody LinkForm f,Authentication a){var l=s.create(a.getName(),f);return Map.of("id",l.getId(),"code",l.getCode(),"shortUrl","/r/"+l.getCode());} @PutMapping("/{id}") public Object update(@PathVariable Long id,@Valid @RequestBody LinkForm f,Authentication a){var l=s.update(a.getName(),id,f);return Map.of("id",l.getId(),"code",l.getCode(),"url",l.getOriginalUrl());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id,Authentication a){s.delete(a.getName(),id);return ResponseEntity.noContent().build();}}
